// userRepo.ts
type User = { id: string; name: string };
const users: User[] = [];
export function addUser(u: User) {
  users.push(u);
}
export function findUser(id: string) {
  return users.find(u => u.id === id);
}
export function getAllUsers() {
  return users;
}

