export const cache: Map<string, any> = new Map();
export function read(key: string) { return cache.get(key); }
export function write(key: string, value: any) { cache.set(key, value); }

// Version B
class CacheStore {
  private cache = new Map<string, any>();
  read(key: string) { return this.cache.get(key); }
  write(key: string, value: any) { this.cache.set(key, value); }
}
export const globalCache = new CacheStore();
